//! Table-driven x86-64 encoder for every non-GP form of AsmJit's ISA database: SSE..SSE4.2,
//! AVX/AVX2/FMA/F16C, AVX-512 (all subsets) and AVX10.2, MMX/3DNow!, x87, AVX-512 mask ops,
//! AMX, crypto/hash. Forms are generated by scripts/gen_vec_tables.py (src/x86_64/vec_table.zig);
//! this file implements legacy, VEX, XOP and EVEX encodings (opmask `{k}`/`{z}`, embedded
//! broadcast, `{er}` rounding, `{sae}`, compressed disp8*N, VSIB).
//!
//!     try vec.emit(&buf, .vaddps, .{ vec.zmm(1), vec.zmm(2), vec.mem(x.ptr(.rax, 64), 64) }, .{ .k = 1, .z = true });
//!
//! Form selection follows AsmJit: the first matching legacy/VEX form wins; EVEX is used when the
//! operands need it (zmm, registers 16..31, opmask, broadcast, rounding/SAE) or `.evex = true`.

const std = @import("std");
const core = @import("../core/code_buffer.zig");
const x = @import("assembler.zig");
const gp = @import("gp.zig");
pub const tbl = @import("vec_table.zig");
pub const Mnemonic = tbl.Mnemonic;
const CodeBuffer = core.CodeBuffer;
const Gp = x.Gp;

pub const Error = core.Error || error{ InvalidOperand, NoMatchingForm };

pub const Kind = enum(u8) { xmm, ymm, zmm, mm, k, tmm, st0, sti, r8, r16, r32, r64, ax, al, cl, eax, rax, dx, mem, vx, vy, vz, imm, maddr, sreg, creg, dreg, fs, gs };

pub const OpKind = struct { k: Kind, size: u16 = 0, bcst: u8 = 0 };

pub const Enc = enum(u2) { legacy, vex, xop, evex };

pub const Form = struct {
    ops: []const OpKind,
    enc: Enc,
    pre: []const u8,
    rexw: bool,
    /// legacy: 0 none, 1 0F, 2 0F38, 3 0F3A, 4 0F0F (3DNow!); VEX/EVEX: mmmmm; XOP: 8/9/A.
    map: u8,
    op: []const u8,
    digit: ?u3,
    imm: u8,
    pp: u2,
    /// 0, 1, 2 = WIG
    w: u2,
    l: u2,
    reg: ?u3,
    rm: ?u3,
    vvvv: ?u3,
    is4: ?u3,
    plus: ?u3,
    /// 0 none, 1 {k}, 2 {k}{z}
    mask: u2,
    er: bool,
    sae: bool,
    /// EVEX disp8 scale for a non-broadcast memory operand.
    n: u8,
    /// Memory form reached through a GP `r/m` alternative (`vmovq r64/m64, xmm`): picked last.
    lowprio: bool = false,
    /// VEX form of an ISA extension newer than its EVEX twin (AVX-IFMA, AVX-VNNI,
    /// AVX-NE-CONVERT): AsmJit uses EVEX unless `.vex = true`.
    late_vex: bool = false,
    /// Memory operand must be explicitly sized (`mov word_ptr, sreg` takes 66, unsized does not).
    exact_mem: bool = false,
};

pub const Cls = enum(u4) { xmm, ymm, zmm, mm, k, tmm, st, seg, cr, dr };

/// Vector / mask / MMX / x87 / AMX register.
pub const V = struct { cls: Cls, id: u5 };
pub inline fn xmm(i: u5) V {
    return .{ .cls = .xmm, .id = i };
}
pub inline fn ymm(i: u5) V {
    return .{ .cls = .ymm, .id = i };
}
pub inline fn zmm(i: u5) V {
    return .{ .cls = .zmm, .id = i };
}
pub inline fn mm(i: u5) V {
    return .{ .cls = .mm, .id = i };
}
pub inline fn k(i: u5) V {
    return .{ .cls = .k, .id = i };
}
pub inline fn tmm(i: u5) V {
    return .{ .cls = .tmm, .id = i };
}
pub inline fn st(i: u5) V {
    return .{ .cls = .st, .id = i };
}
/// Segment register: es=0, cs=1, ss=2, ds=3, fs=4, gs=5.
pub inline fn seg(i: u5) V {
    return .{ .cls = .seg, .id = i };
}
pub inline fn cr(i: u5) V {
    return .{ .cls = .cr, .id = i };
}
pub inline fn dr(i: u5) V {
    return .{ .cls = .dr, .id = i };
}

/// Memory operand; `size` in bytes (0 = unsized), `bcst` = broadcast count (`{1toN}`),
/// `vindex` for VSIB (gathers/scatters).
pub const Mem = struct {
    base: ?Gp = null,
    index: ?Gp = null,
    vindex: ?V = null,
    scale: x.Scale = .x1,
    disp: i32 = 0,
    size: u16 = 0,
    bcst: u8 = 0,
    rip: bool = false,
};

pub inline fn mem(m: x.Mem, size: u16) Mem {
    return .{ .base = m.base, .index = m.index, .scale = m.scale, .disp = m.disp, .size = size };
}
/// [base + vindex*scale + disp] (VSIB).
pub inline fn vsib(base: ?Gp, vindex: V, scale: x.Scale, disp: i32, size: u16) Mem {
    return .{ .base = base, .vindex = vindex, .scale = scale, .disp = disp, .size = size };
}
/// Embedded broadcast of an element of `size` bytes, `count` times (`{1toN}`).
pub inline fn bcst(m: Mem, count: u8) Mem {
    var r = m;
    r.bcst = count;
    return r;
}

pub const Rc = enum(u2) { rn, rd, ru, rz };

/// Instruction options: opmask `{k}`, zeroing `{z}`, rounding `{er}`, `{sae}`, force EVEX.
pub const Extra = struct { k: u3 = 0, z: bool = false, rc: ?Rc = null, sae: bool = false, evex: bool = false, vex: bool = false, lock: bool = false, rex: bool = false };

pub const Op = union(enum) { v: V, r: gp.Reg, m: Mem, imm: i64 };

fn toOp(v: anytype) Op {
    const T = @TypeOf(v);
    return switch (T) {
        V => .{ .v = v },
        gp.Reg => .{ .r = v },
        Mem => .{ .m = v },
        Op => v,
        comptime_int => .{ .imm = v },
        else => switch (@typeInfo(T)) {
            .int => .{ .imm = @intCast(v) },
            else => @compileError("unsupported operand type " ++ @typeName(T)),
        },
    };
}

fn vl(l: u2) u16 {
    return @as(u16, 16) << l;
}

fn matchKind(f: Form, kd: OpKind, o: Op) bool {
    switch (o) {
        .v => |v| return switch (kd.k) {
            .xmm => v.cls == .xmm,
            .ymm => v.cls == .ymm,
            .zmm => v.cls == .zmm,
            .mm => v.cls == .mm and v.id < 8,
            .k => v.cls == .k and v.id < 8,
            .tmm => v.cls == .tmm and v.id < 8,
            .st0 => v.cls == .st and v.id == 0,
            .sti => v.cls == .st and v.id < 8,
            .sreg => v.cls == .seg and v.id < 6,
            .creg => v.cls == .cr and v.id < 16,
            .dreg => v.cls == .dr and v.id < 16,
            .fs => v.cls == .seg and v.id == 4,
            .gs => v.cls == .seg and v.id == 5,
            else => false,
        },
        .r => |r| return switch (kd.k) {
            .r8 => r.size == .b,
            .r16 => r.size == .w,
            .r32 => r.size == .d,
            .r64 => r.size == .q,
            .ax => r.size == .w and r.id == .rax and !r.high,
            .al => r.size == .b and r.id == .rax and !r.high,
            .cl => r.size == .b and r.id == .rcx and !r.high,
            .eax => r.size == .d and r.id == .rax,
            .rax => r.size == .q and r.id == .rax,
            .dx => r.size == .w and r.id == .rdx,
            else => false,
        },
        .m => |m| switch (kd.k) {
            .mem => {
                if (m.vindex != null) return false;
                if (m.bcst != 0) {
                    if (kd.bcst == 0) return false;
                    if (m.size != 0 and m.size != kd.bcst) return false;
                    return @as(u16, m.bcst) * kd.bcst == (if (kd.size != 0) kd.size else vl(f.l));
                }
                if (f.exact_mem) return m.size == kd.size;
                return m.size == 0 or kd.size == 0 or m.size == kd.size;
            },
            // umonitor: `[reg]` encoded as the register in ModRM.rm (mod = 11).
            .maddr => return m.base != null and m.index == null and m.vindex == null and m.disp == 0 and !m.rip,
            .vx, .vy, .vz => {
                const vi = m.vindex orelse return false;
                const want: Cls = switch (kd.k) {
                    .vx => .xmm,
                    .vy => .ymm,
                    else => .zmm,
                };
                return vi.cls == want and m.bcst == 0;
            },
            else => return false,
        },
        .imm => |v| return kd.k == .imm and (kd.size >= 8 or fitsN(v, kd.size)),
    }
}

fn fitsN(v: i64, bytes: u16) bool {
    const bits: u6 = @intCast(bytes * 8);
    return v >= -(@as(i64, 1) << (bits - 1)) and v < (@as(i64, 1) << bits);
}

fn regNum(o: Op) u8 {
    return switch (o) {
        .v => |v| v.id,
        .r => |r| if (r.high) @as(u8, @intFromEnum(r.id)) + 4 else @intFromEnum(r.id),
        // enqcmd/movdir64b: the destination `es:[reg]` is encoded as the register in ModRM.reg.
        .m => |m| if (m.base) |b| @intFromEnum(b) else 0,
        .imm => 0,
    };
}

fn matches(f: Form, ops: []const Op, e: Extra) bool {
    if (f.ops.len != ops.len) return false;
    for (f.ops, ops) |kd, o| if (!matchKind(f, kd, o)) return false;
    const evex = f.enc == .evex;
    if (!evex) {
        if (e.k != 0 or e.z or e.rc != null or e.sae or e.evex) return false;
        for (ops) |o| switch (o) {
            .v => |v| if (v.id >= 16) return false,
            .m => |m| if (m.vindex) |vi| if (vi.id >= 16) return false,
            else => {},
        };
    } else {
        if (e.k != 0 and f.mask == 0) return false;
        if (e.z and f.mask != 2) return false;
        if (e.rc != null and !f.er) return false;
        if (e.sae and !f.sae) return false;
        // {er}/{sae} only with register operands.
        if (e.rc != null or e.sae) for (ops) |o| if (o == .m) return false;
    }
    return true;
}

const Buf = gp.Buf;

fn fitsI8(v: i64) bool {
    return v >= -128 and v <= 127;
}

/// ModRM (+SIB, disp) for memory `m` with reg field `r3`; `n` = EVEX disp8 scale (1 otherwise).
fn modrmMem(out: *Buf, r3: u8, m: Mem, n: u8, force_sib: bool) ?u8 {
    const r = (r3 & 7) << 3;
    if (m.rip) {
        out.u8_(r | 5);
        const at = out.n;
        out.int(m.disp, 4);
        return at;
    }
    const idx: ?u8 = if (m.vindex) |vi| vi.id else if (m.index) |g| @intFromEnum(g) else null;
    const sc: u8 = @as(u8, @intFromEnum(m.scale)) << 6;
    if (m.base) |base| {
        const b: u8 = @intFromEnum(base);
        var disp8: ?i64 = null;
        if (m.disp == 0 and (b & 7) != 5) {
            disp8 = null;
        } else if (@rem(m.disp, n) == 0 and fitsI8(@divTrunc(m.disp, n))) disp8 = @divTrunc(m.disp, n);
        const mod: u8 = if (m.disp == 0 and (b & 7) != 5) 0x00 else if (disp8 != null) 0x40 else 0x80;
        if (idx != null or (b & 7) == 4 or force_sib) {
            out.u8_(mod | r | 4);
            out.u8_(sc | ((if (idx) |i| i else 4) & 7) << 3 | (b & 7));
        } else out.u8_(mod | r | (b & 7));
        if (mod == 0x40) out.int(disp8.?, 1) else if (mod == 0x80) out.int(m.disp, 4);
    } else {
        out.u8_(r | 4);
        out.u8_(sc | ((if (idx) |i| i else 4) & 7) << 3 | 5);
        out.int(m.disp, 4);
    }
    return null;
}

pub fn encodeForm(f: Form, ops: []const Op, e: Extra, out: *Buf) Error!?u8 {
    var reg: u8 = f.digit orelse 0;
    if (f.reg) |i| reg = regNum(ops[i]);
    var rm_reg: ?u8 = null;
    var rm_mem: ?Mem = null;
    if (f.rm) |i| switch (ops[i]) {
        .m => |m| if (f.ops[i].k == .maddr) {
            rm_reg = @intFromEnum(m.base.?);
        } else {
            rm_mem = m;
        },
        .imm => return error.InvalidOperand,
        else => rm_reg = regNum(ops[i]),
    };
    if (f.plus) |i| rm_reg = regNum(ops[i]);
    const vvvv: u8 = if (f.vvvv) |i| regNum(ops[i]) else 0;
    var bcst_elem: u8 = 0;
    if (rm_mem) |m| {
        if (m.bcst != 0) {
            for (f.ops) |kd| if (kd.k == .mem) {
                bcst_elem = kd.bcst;
            };
        }
        if (m.index == .rsp) return error.InvalidOperand;
    }
    // Bits of the r/m side: B (base or rm reg bit 3), X (index bit 3, or rm reg bit 4 in EVEX).
    var b3: u8 = 0;
    var x3: u8 = 0;
    var v4: u8 = (vvvv >> 4) & 1;
    if (rm_reg) |rr| {
        b3 = (rr >> 3) & 1;
        x3 = (rr >> 4) & 1;
    } else if (rm_mem) |m| {
        if (m.base) |bb| b3 = (@intFromEnum(bb) >> 3) & 1;
        if (m.index) |ii| x3 = (@intFromEnum(ii) >> 3) & 1;
        if (m.vindex) |vi| {
            x3 = (vi.id >> 3) & 1;
            v4 = (vi.id >> 4) & 1;
        }
    }
    const r3: u8 = (reg >> 3) & 1;
    const r4: u8 = (reg >> 4) & 1;
    const w: u8 = if (f.w == 1) 1 else 0;
    var tail_op = false;
    switch (f.enc) {
        .legacy => {
            for (f.pre) |p| out.u8_(p);
            var need_rex = false;
            var has_high = false;
            for (ops) |o| if (o == .r) {
                if (o.r.high) has_high = true else if (o.r.size == .b and @intFromEnum(o.r.id) >= 4 and @intFromEnum(o.r.id) < 8) need_rex = true;
            };
            var rexv: u8 = (if (f.rexw) @as(u8, 8) else 0) | r3 << 2 | (if (rm_mem != null) x3 else 0) << 1 | b3;
            if (rm_reg != null) rexv &= 0b1101;
            if (rexv != 0 or need_rex or e.rex) {
                if (has_high) return error.InvalidOperand;
                out.u8_(0x40 | rexv);
            }
            switch (f.map) {
                0 => {},
                1 => out.u8_(0x0F),
                2 => {
                    out.u8_(0x0F);
                    out.u8_(0x38);
                },
                3 => {
                    out.u8_(0x0F);
                    out.u8_(0x3A);
                },
                else => {
                    out.u8_(0x0F);
                    out.u8_(0x0F);
                    tail_op = true;
                },
            }
        },
        .vex, .xop => {
            const R = (~r3 & 1) << 7;
            const X = (~x3 & 1) << 6;
            const B = (~b3 & 1) << 5;
            const vv = (~vvvv & 15) << 3;
            const L = @as(u8, f.l & 1) << 2;
            if (f.enc == .vex and f.map == 1 and w == 0 and x3 == 0 and b3 == 0) {
                out.u8_(0xC5);
                out.u8_(R | vv | L | f.pp);
            } else {
                out.u8_(if (f.enc == .vex) 0xC4 else 0x8F);
                out.u8_(R | X | B | f.map);
                out.u8_(w << 7 | vv | L | f.pp);
            }
        },
        .evex => {
            if (rm_reg != null and rm_mem == null) {} else if (rm_mem == null and f.rm == null) x3 = 0;
            out.u8_(0x62);
            out.u8_((~r3 & 1) << 7 | (~x3 & 1) << 6 | (~b3 & 1) << 5 | (~r4 & 1) << 4 | (f.map & 7));
            out.u8_(w << 7 | (~vvvv & 15) << 3 | 4 | f.pp);
            // {er}: L'L carries the rounding mode; {sae} alone: AsmJit writes L'L = 0.
            const ll: u8 = if (e.rc) |rc| @intFromEnum(rc) else if (e.sae) 0 else f.l;
            const bbit: u8 = if (bcst_elem != 0 or e.rc != null or e.sae) 1 else 0;
            out.u8_((if (e.z) @as(u8, 0x80) else 0) | ll << 5 | bbit << 4 | (~v4 & 1) << 3 | e.k);
        },
    }
    if (!tail_op) for (f.op, 0..) |bt, i| {
        out.u8_(if (f.plus != null and i == f.op.len - 1) bt + (rm_reg.? & 7) else bt);
    };
    var rip_at: ?u8 = null;
    if (f.rm != null) {
        if (rm_reg) |rr| {
            if (f.plus == null) out.u8_(0xC0 | (reg & 7) << 3 | (rr & 7));
        } else if (rm_mem) |m| {
            const n: u8 = if (f.enc != .evex) 1 else if (bcst_elem != 0) bcst_elem else f.n;
            rip_at = modrmMem(out, reg, m, n, false);
        }
    } else if ((f.digit != null or f.reg != null) and f.plus == null) {
        out.u8_(0xC0 | (reg & 7) << 3); // reg-only ModRM (11:rrr:000, e.g. tilezero)
    }
    if (tail_op) for (f.op) |bt| out.u8_(bt);
    // Immediates: is4 register in imm[7:4] (+ optional imm4), then the remaining imm bytes.
    var imm_left: u8 = f.imm;
    var is4_done = false;
    if (f.is4) |i| {
        var v: u8 = regNum(ops[i]) << 4;
        for (ops) |o| if (o == .imm) {
            v |= @as(u8, @truncate(@as(u64, @bitCast(o.imm)))) & 0xF;
        };
        out.u8_(v);
        is4_done = true;
    }
    if (!is4_done) {
        for (f.ops, ops) |kd, o| if (kd.k == .imm and imm_left > 0) {
            const nb: u8 = @intCast(@max(kd.size, 1));
            out.int(o.imm, nb);
            imm_left -|= nb;
        };
    }
    return rip_at;
}

/// Emits `mn` with operands `args` (tuple of `V` / `gp.Reg` / `Mem` / integers).
pub fn emit(buf: *CodeBuffer, comptime mn: Mnemonic, args: anytype, e: Extra) Error!void {
    var ops: [args.len]Op = undefined;
    inline for (args, 0..) |a, i| ops[i] = toOp(a);
    return emitOps(buf, &@field(tbl.table, @tagName(mn)), &ops, e);
}

fn allRegs(ops: []const Op) bool {
    for (ops) |o| if (o == .m) return false;
    return true;
}

/// AsmJit order: legacy/VEX before EVEX; for register-only operands the load-style form (first
/// operand in ModRM.reg) before the store-style one (`mr`, `mvr`).
fn pick(forms: []const Form, ops: []const Op, e: Extra) ?Form {
    return pickEx(forms, ops, e, false);
}

fn has67(f: Form) bool {
    for (f.pre) |p| if (p == 0x67) return true;
    return false;
}

fn pickEx(forms: []const Form, ops: []const Op, e: Extra, no67: bool) ?Form {
    const regs = allRegs(ops);
    // 0: legacy/VEX preferred, 1: legacy/VEX any (not PreferEvex), 2: EVEX preferred,
    // 3: EVEX any, 4: VEX of a PreferEvex instruction.
    for (0..5) |level| {
        for (forms) |f| {
            const evex = f.enc == .evex;
            if (evex != (level == 2 or level == 3)) continue;
            const preferred = !(regs and f.rm != null and f.rm.? == 0 and f.reg != null) and !f.lowprio and
                !(regs and f.w == 1 and f.enc == .xop);
            switch (level) {
                0 => if (!preferred or (f.late_vex and !e.vex)) continue,
                1 => if (f.late_vex and !e.vex) continue,
                2 => if (!preferred) continue,
                3 => {},
                else => if (!f.late_vex) continue,
            }
            if (no67 and has67(f)) continue;
            if (matches(f, ops, e)) return f;
        }
    }
    return null;
}

fn isImplicit(o: Op) bool {
    return switch (o) {
        .v => |v| (v.cls == .xmm and v.id == 0) or v.cls == .k,
        .r => |r| !r.high and (r.id == .rax or r.id == .rcx or r.id == .rdx or r.id == .rbx or r.id == .rdi or r.id == .rsi),
        .m => |m| m.base != null and m.index == null and m.vindex == null and m.disp == 0 and !m.rip,
        .imm => false,
    };
}

/// AsmJit spellings with explicit implicit operands (`blendvps(x, y, xmm0)`,
/// `pcmpistri(x, y, imm, ecx)`, `vp2intersectd(k2, k3, ...)`, `maskmovq(ptr(rdi), mm, mm)`):
/// retried with implicit operands removed from either end (or `k+1` after the first operand).
fn pickAliased(forms: []const Form, ops: []const Op, e: Extra, tmp: []Op) ?struct { f: Form, ops: []const Op } {
    if (ops.len >= 2 and ops[0] == .v and ops[1] == .v and ops[0].v.cls == .k and ops[1].v.cls == .k and ops[1].v.id == ops[0].v.id + 1) {
        tmp[0] = ops[0];
        for (ops[2..], 1..) |o, i| tmp[i] = o;
        if (pick(forms, tmp[0 .. ops.len - 1], e)) |f| return .{ .f = f, .ops = tmp[0 .. ops.len - 1] };
    }
    var lo: usize = 0;
    while (lo <= ops.len) : (lo += 1) {
        var hi: usize = ops.len;
        while (hi >= lo) : (hi -= 1) {
            if (lo != 0 or hi != ops.len) {
                var ok = true;
                for (ops[0..lo]) |o| ok = ok and isImplicit(o);
                for (ops[hi..]) |o| ok = ok and isImplicit(o);
                // A dropped 64-bit address register (`invlpga(rax, ecx)`) excludes the 67 form.
                var wide = false;
                for (ops[0..lo]) |o| wide = wide or (o == .r and o.r.size == .q);
                for (ops[hi..]) |o| wide = wide or (o == .r and o.r.size == .q);
                if (ok) if (pickEx(forms, ops[lo..hi], e, wide)) |f| return .{ .f = f, .ops = ops[lo..hi] };
            }
            if (hi == lo) break;
        }
        if (lo < ops.len and !isImplicit(ops[lo])) break;
    }
    return null;
}

pub fn emitOps(buf: *CodeBuffer, forms: []const Form, ops_in: []const Op, e: Extra) Error!void {
    var ops = ops_in;
    var tmp: [8]Op = undefined;
    var chosen = pick(forms, ops, e);
    if (chosen == null and ops.len <= tmp.len) if (pickAliased(forms, ops, e, &tmp)) |a| {
        chosen = a.f;
        ops = a.ops;
    };
    const f = chosen orelse return error.NoMatchingForm;
    var b: Buf = .{};
    _ = try encodeForm(f, ops, e, &b);
    try buf.ensure(18);
    if (e.lock) buf.put8(0xF0);
    for (b.b[0..b.n]) |bt| buf.put8(bt);
}
